// Links the Windows resources (icon, version info, manifest) generated by build.sh into the exe.
fn main() {
    println!("cargo:rerun-if-changed=winres/rsrc_windows_amd64.syso");
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() != Ok("windows") {
        return;
    }
    let res = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("winres/rsrc_windows_amd64.syso");
    if res.exists() {
        // A COFF object; some linkers (zig cc) only accept it with an object-file extension.
        let obj = std::path::Path::new(&std::env::var("OUT_DIR").unwrap()).join("resources.o");
        std::fs::copy(&res, &obj).expect("copy Windows resources");
        println!("cargo:rustc-link-arg-bins={}", obj.display());
    } else {
        println!("cargo:warning=winres/rsrc_windows_amd64.syso not found: the exe will have no icon. Run build.sh.");
    }
}
